mapper.select:
SELECT
    s.id,
    s.schedule_title,
    s.start_time,
    s.end_time,
    s.need_notice,
    s.auto_finish,
    s.notice_time,
    s.notice_time_type,
    d.dict_label noticeTimeTypeName,
    s.mark_color,
    s.remark,
    s.create_by,
    s.batch_id,
    s.task_id,
    s.OWNER,
    s.owner_ids,
    s.owner_names,
    s.status,
    u.nick_name ownerName ,
    u1.nick_name createByName,
    d1.dict_label statusName
FROM
    pa_schedule s
    LEFT JOIN ( SELECT dict_code, dict_value, dict_label FROM sys_dict_data WHERE dict_type = 'anchor_type' ) d ON d.dict_value = s.notice_time_type
    LEFT JOIN ( SELECT dict_code, dict_value, dict_label FROM sys_dict_data WHERE dict_type = 'schedule_status' ) d1 ON d1.dict_value = s.status
    LEFT JOIN sys_user u ON s.OWNER = u.user_id
    LEFT JOIN sys_user u1 ON s.create_by = u1.user_id

     and s.schedule_title = #{scheduleTitle}
     and s.start_time >= #{startTime}
     and s.start_time <= #{endTime}
     and s.need_notice = #{needNotice}
     and s.auto_finish = #{autoFinish}
     and s.notice_time = #{noticeTime}
     and s.notice_time_type = #{noticeTimeType}
     and s.mark_color = #{markColor}
     and s.batch_id = #{batchId}
     and s.task_id = #{taskId}
     and s.owner = #{owner}
     and s.owner_ids = #{ownerIds}
     and s.owner_names = #{ownerNames}
     and s.status = #{status}

mapper.update:
update pa_schedule
schedule_title = #{scheduleTitle}, start_time = #{startTime}, end_time = #{endTime}, need_notice = #{needNotice}, auto_finish = #{autoFinish}, notice_time = #{noticeTime}, notice_time_type = #{noticeTimeType}, mark_color = #{markColor}, remark = #{remark}, create_by = #{createBy}, batch_id = #{batchId}, task_id = #{taskId}, owner = #{owner}, owner_ids = #{ownerIds}, owner_names = #{ownerNames}, status = #{status},
where id = #{id}
